import {controller} from '@github/catalyst'

@controller('codespaces-user-settings')
export class CodespacesUserSettingsElement extends HTMLElement {
  #wasFocused: string | null = null
  #focusedAttrType: 'id' | 'name' | 'href' | null = null

  // Bound arrow function stored as a private field so it can be removed later
  #boundFocusIn = (event: FocusEvent) => {
    const el = event.target as HTMLElement | null
    if (!el) return
    if (el instanceof HTMLInputElement || el instanceof HTMLSelectElement) {
      this.#wasFocused = el.id ? el.id : el.name || null
      this.#focusedAttrType = el.id ? 'id' : 'name'
    } else if (el instanceof HTMLAnchorElement) {
      this.#wasFocused = el.href || null
      this.#focusedAttrType = 'href'
    } else {
      this.#wasFocused = null
      this.#focusedAttrType = null
    }
  }

  // Handle Turbo frame load for #settings-frame and restore focus if possible
  #boundFrameLoad = (event: Event) => {
    const target = event.target as HTMLElement | null
    if (!target || typeof target.matches !== 'function') return
    if (!target.matches('turbo-frame#settings-frame')) return
    let toFocus: Element | null = null
    if (this.#wasFocused) {
      if (this.#focusedAttrType === 'id') {
        toFocus = document.getElementById(this.#wasFocused)
      } else if (this.#focusedAttrType === 'name') {
        const list = document.getElementsByName(this.#wasFocused)
        toFocus = (list && list[0]) || null
      } else if (this.#focusedAttrType === 'href') {
        toFocus = document.querySelector(`a[href='${CSS.escape(this.#wasFocused)}']`)
      }
    }
    if (toFocus instanceof HTMLElement) {
      toFocus.focus()
    }
  }

  connectedCallback() {
    document.addEventListener('focusin', this.#boundFocusIn)
    document.addEventListener('turbo:frame-load', this.#boundFrameLoad)
  }

  disconnectedCallback() {
    document.removeEventListener('focusin', this.#boundFocusIn)
    document.removeEventListener('turbo:frame-load', this.#boundFrameLoad)
  }

  // Public getters to expose the tracked values if needed
  get lastFocused() {
    return this.#wasFocused
  }

  get lastFocusedAttrType() {
    return this.#focusedAttrType
  }
}
